@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _pricing = new();

    private int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        _pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier)).TotalCents;

    [Fact]
    public void S1_BronzeCustomerIsChargedBronzePrice()
    {
        // Bronze customer is charged the Bronze price for a basket
        Assert.Equal(9500, ChargedFor(LoyaltyTier.Bronze, 10000));
    }

    [Fact]
    public void S2_SilverCustomerIsChargedSilverPrice()
    {
        // Silver customer is charged the Silver price for a basket
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));
    }

    [Fact]
    public void S3_GoldCustomerIsChargedGoldPrice()
    {
        // Gold customer is charged the Gold price for a basket
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));
    }

    [Fact]
    public void S4_BronzeReductionLandsOnWholeCentInCustomersFavour()
    {
        // Bronze customer's reduction lands on a whole cent in their favour
        Assert.Equal(7, ChargedFor(LoyaltyTier.Bronze, 7));
    }
}
EOF
